  "Your story": "قصتك", "Talk to the neighbour with a ★ above their head.": "تحدّث إلى الجار الذي فوق رأسه ★.", "Finish the previous chapter first.": "أنهِ الفصل السابق أولاً.", "chapter {n} of {n2}": "الفصل {n} من {n2}", "Act I": "الفصل الأول من القصة", "Act II": "الجزء الثاني", "· chapter {n} of {n2} · Act I": "· الفصل {n} من {n2} · الجزء الأول", "· chapter {n} of {n2} · Act II": "· الفصل {n} من {n2} · الجزء الثاني", "complete!": "اكتملت!",
